import { expectStatus, expect, test, USERS, PASSWORD } from "../../fixtures";

test.describe("LIF-15 vendor lifecycle", () => {
  test(
    "A page past the last vendor is empty but still reports the total",
    { tag: "@LIF-15" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");

      const firstResponse = await member.get("/api/vendors", {
        params: { limit: 20, offset: 0 },
      });
      const firstPage = await expectStatus<{
        items: unknown[];
        total: number;
        limit: number;
        offset: number;
      }>(firstResponse, 200);

      const pastOffset = firstPage.total + 1000;

      // Act
      const response = await member.get("/api/vendors", {
        params: { limit: 20, offset: pastOffset },
      });

      // Assert
      const body = await expectStatus<{
        items: unknown[];
        total: number;
        limit: number;
        offset: number;
      }>(response, 200);
      expect(body.items).toEqual([]);
      expect(body.total).toBe(firstPage.total);
      expect(body.offset).toBe(pastOffset);
    },
  );
});
